def discard(self, n=-1, qid=-1, dehydration_hooks=None, hydration_hooks=None, **handlers):
    """
    Appends a DISCARD message to the output queue.

    :param n: number of records to discard, default = -1 (ALL)
    :param qid: query ID to discard for, default = -1 (last query)
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration function).
        Dehydration functions receive the value and returns an object of type
        understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to dehydration function).
        Dehydration functions receive the value of type understood by packstream and
        are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    """

    if n < 0 and qid < 0:
        raise ValueError("you must specify at least one of 'n' or 'qid'")

    if n < 0:
        n = self.cardinality

    if qid < 0:
        qid = self.prev_qid

    if dehydration_hooks is None:
        dehydration_hooks = {}

    if hydration_hooks is None:
        hydration_hooks = {}

    response = Response(n=n, qid=qid, **handlers)

    for i in range(n):
        record = self.discard_record()
        response.add_record(record, dehydrate_values=False)

    if hydration_hooks:
        for record in response.records:
            for key, value in record.items():
                if type(value) in hydration_hooks:
                    hydration = hydration_hooks[type(value)]
                    record[key] = hydration(value)

    response.output = self.add_metadata(response.output)

    return response

