        self.append(bookmarks=[ {"marker": bookmark} for bookmark in bookmarks ])
    if metadata:
        self.append(begin_fields="metadata", begin={"metadata": metadata})
    if timeout is not None:
        self.append(begin="TIMEOUT", begin_timeout=timeout)
    if db:
        self.append(begin="DATABASE", begin_database=db)
    if imp_user:
        self.append(begin="IMPERSONATE", begin_impersonate=imp_user)
    if dehydration_hooks:
        for type_, dehydrate in dehydration_hooks.items():
            self.append(begin="DEHYDRATE", begin_dehydrate={type_: dehydrate})
    if hydration_hooks:
        for type_, hydrate in hydration_hooks.items():
            self.append(begin="HYDRATE", begin_hydrate={type_: hydrate})
    if handlers:
        self.append(handlers=handlers)
    return self.begin()

