def xargs(cmd, varargs, color=False, target_concurrency=1, _max_length=_get_platform_max_length(), **kwargs):
    if not isinstance(cmd, tuple):
        raise TypeError("cmd must be a tuple")
    if not isinstance(varargs, collections.Sequence):
        raise TypeError("varargs must be a sequence")
    if not isinstance(color, bool):
        raise TypeError("color must be a boolean")
    if not isinstance(target_concurrency, int):
        raise TypeError("target_concurrency must be an integer")
    if not isinstance(_max_length, int):
        raise TypeError("_max_length must be an integer")

    # Split varargs into partitions of size at most _max_length
    partitions = []
    partition = []
    for arg in varargs:
        if len(partition) + len(arg) < _max_length:
            partition.append(arg)
        else:
            partitions.append(partition)
            partition = [arg]
    partitions.append(partition)

    # Run each partition in a subprocess
    results = []
    with concurrent.futures.ThreadPoolExecutor(max_workers=target_concurrency) as executor:
        for partition in partitions:
            future = executor.submit(
                _run_partition,
                cmd,
                partition,
                color=color,
                **kwargs,
            )
            results.append(future.result())

    # Return the exit code and the combined stdout of all subprocesses
    return (
        results[0][0],
        b"".join(result[1] for result in results),
