def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for field in observer_schema:
        if field not in response:
            raise KeyError(f"Field {field} is not present in response")
        if field not in last_applied_manifest:
            last_applied_manifest[field] = response[field]
        elif isinstance(last_applied_manifest[field], dict):
            last_applied_manifest[field] = update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[field],
                observer_schema[field],
                response[field],
            )
        elif isinstance(last_applied_manifest[field], list):
            for i, sub_field in enumerate(observer_schema[field]):
                if sub_field not in response[field]:
                    raise KeyError(
                        f"Field {sub_field} is not present in response for list item {i}"
                    )
                if not isinstance(response[field][sub_field], dict):
                    raise ValueError(
                        f"Field {sub_field} is not a dict and cannot be used as a sub-field"
                    )
                last_applied_manifest[field][i] = update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[field][i],
                    observer_schema[field][sub_field],
                    response[field][sub_field],
                )
