def generate_default_observer_schema(app: "krake.data.kubernetes.Application"):
    """Generate a default observer schema based on the `spec.manifest` of the passed application.

    Return:
        `json:bool`: A JSON schema for observers based on the application's `spec.manifest` structured as a dict of the form:
        {
            "observers": {
                "k8s": {
                    "custom_observers": {
                        ...
                    },
                    "default_observers": {
                        ...
                    }
                }
            }
        }
    """

    if not app.is_deployed():
        return False

    default_observers = {}
    for resource in app.spec.manifest:
        if resource.metadata.name in app.metadata.observers_spec.default_observers:
            continue

        observers = app.metadata.observers_spec.default_observers[resource.metadata.name]
        for observer in observers:
            if observer.name not in default_observers:
                default_observers[observer.name] = {}
            default_observers[observer.name][resource.metadata.name] = observer.spec

    return {"observers": {"k8s": {"custom_observers": {}, "default_observers": default_observers}}}

def format(self, sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    if isinstance(params, dict):
        # Convert params from named to ordinal style
        params = {i: param for i, param in enumerate(params.values())}
    elif isinstance(params, Sequence):
        # Convert params from ordinal to named style
        params = {i: param for i, param in enumerate(params)}
    else:
        raise ValueError("Invalid type for params. Must be dict or sequence.")

    # Replace in-style params with out-style params in sql
    formatted_sql = re.sub(r"[:][a-z]+\b", "", sql)

    return formatted_sql, params

def format(self, sql, params):
    # Handle invalid inputs
    if not isinstance(sql, (str, bytes)):
        raise TypeError("sql must be a string or bytes")
    if not isinstance(params, (list, dict)):
        raise TypeError("params must be a list or dict")

    # Convert to out-style parameters
    out_params = {}
    if isinstance(params, list):
        for i, value in enumerate(params):
            out_params[f"@{i}"] = value
    elif isinstance(params, dict):
        for key, value in params.items():
            out_params[f"@{key}"] = value
    else:
        raise TypeError("params must be a list or dict")

    # Replace parameters in SQL query
    sql = sql.replace("?", "@{}")

    return sql, out_params

def format(self, sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    # Determine the parameter style based on the type of params
    if isinstance(params, Mapping):
        # Named parameter style
        param_style = ":{key}"
    else:
        # Ordinal parameter style
        param_style = "?"

    # Replace the in-style parameters with out-style parameters
    sql = re.sub(r":[a-z0-9_]+", param_style, sql)

    # Convert the parameters to a dict if necessary
    if isinstance(params, Mapping):
        params = {param_style.format(key=key): value for key, value in params.items()}
    elif isinstance(params, Sequence):
        params = OrderedDict([(param_style.format(idx=idx), value) for idx, value in enumerate(params)])

    # Return the formatted SQL query and the converted parameters
    return sql, params

def format(self, sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    """
    Convert the SQL query to use the out-style parameters instead of the in-style parameters.
    """
    if isinstance(params, Dict):
        out_params = {}
        for k, v in params.items():
            if isinstance(k, str) or isinstance(k, int):
                out_params[f"@p{k}"] = v
            else:
                raise ValueError("Invalid parameter key type")
        return (sql.replace("%s", "@p{}"), out_params)
    elif isinstance(params, Sequence):
        out_params = []
        for i, v in enumerate(params):
            out_params.append(f"@p{i+1}")
        return (sql.replace("%s", "@p{}"), out_params)
    else:
        raise ValueError("Invalid params type")

def format(sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    in_params = params.copy()
    out_params = {}
    for param in params:
        if param in in_params:
            in_params.pop(param)
            out_params[param] = params[param]
    return (sql.format(out_params), out_params)

def formatmany(self, sql: AnyStr, many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]]) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    if not sql:
        raise ValueError("sql argument is required")
    if not many_params:
        raise ValueError("many_params argument is required")

    formatted_sql = sql
    out_params = []

    for params in many_params:
        if not params:
            raise ValueError("params argument is required")

        out_params.append(self._format_params(params))

    return formatted_sql, out_params

