def check_digests_present_and_used(manifest_files, digests_used):
    if not manifest_files or not digests_used:
        raise ValueError("Input parameters cannot be empty")
    digests_needed = set(digests_used)
    digests_present = set()
    manifest_files = iter(manifest_files)
    for manifest in manifest_files:
        for digest in manifest.get("digests", []):
            digests_present.add(digest)
            if digest in digests_needed:
                digests_needed.remove(digest)
                if not digests_needed:
                    break
        if not digests_needed:
            break
    return len(digests_needed) == 0 and len(digests_present) == len(manifest_files)

