def validate_fixity(manifest_files, fixity):
    # Check if the fixity block is a list
    if not isinstance(fixity, list):
        raise TypeError("Fixity block must be a list")

    # Check if the fixity block is not empty
    if len(fixity) == 0:
        raise ValueError("Fixity block must not be empty")

    # Check if all items in the fixity block are strings
    if not all(isinstance(item, str) for item in fixity):
        raise ValueError("All items in fixity block must be strings")

    # Check if all files listed in the manifest are referenced in the fixity block
    for file in manifest_files:
        if not file in fixity:
            raise ValueError("File {} is not referenced in the fixity block".format(file))

    # Check if all items in the fixity block refer to existing files in the manifest
    for item in fixity:
        if not item in manifest_files:
            raise ValueError("Item {} does not reference a valid file".format(item))

    # If all checks pass, return the validated fixity block
    return fixity

def validate_fixity(fixity, manifest_files):
    # Check that fixity block exists and is non-empty
    if not fixity or not fixity.strip():
        raise ValueError("Fixity block is missing or empty")

    # Parse fixity block
    try:
        fixity_dict = json.loads(fixity)
    except ValueError:
        raise ValueError("Fixity block is not valid JSON")

    # Check that fixity block is a dict
    if not isinstance(fixity_dict, dict):
        raise ValueError("Fixity block is not a dict")

    # Check that fixity block contains all required keys
    required_keys = ["checksumAlg", "filenames", "checksum"]
    for key in required_keys:
        if key not in fixity_dict:
            raise ValueError(f"Required key {key} is missing from fixity block")

    # Check that filenames listed in fixity block are in the manifest
    for filename in fixity_dict["filenames"]:
        if filename not in manifest_files:
            raise ValueError(f"Filename {filename} is not in manifest")

    # Check that checksums are valid
    checksum_regex = r"[a-fA-F\d]+"
    for checksum in fixity_dict["checksum"]:
        if not re.match(checksum_regex, checksum):
            raise ValueError(f"Checksum {checksum} is not valid")

def validate_fixity(fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # make sure fixity is a list
    if not isinstance(fixity, list):
        raise ValueError("Invalid fixity block provided")

    # make sure manifest_files is a list
    if not isinstance(manifest_files, list):
        raise ValueError("Invalid manifest files provided")

    # check that there are no duplicate file paths in the manifest
    if len(manifest_files) != len(set(manifest_files)):
        raise ValueError("Manifest files contain duplicate file paths")

    # check that all entries in the fixity block have a corresponding file in the manifest
    for fixity_entry in fixity:
        file_path = fixity_entry["file_path"]
        if not any(file_path in manifest_file["file_path"] for manifest_file in manifest_files):
            raise ValueError("Fixity block contains unrecognized file: {}".format(file_path))

    # check that the fixity block is properly formatted
    for fixity_entry in fixity:
        file_path = fixity_entry["file_path"]
        # make sure fixity type is valid
        if fixity_entry["type"] not in ["md5", "sha1", "sha256"]:
            raise ValueError("Invalid fixity type for file: {}".format(file_path))

        # make sure fixity value is a valid hash value
        if not re.match(r"[A-F0-9]{32}", fixity_entry["value"]):
            raise ValueError("Invalid fixity value for file: {}".format(file_path))

    return fixity

