def _extract_number_and_supplement_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis:
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    # Get the text from the <issue> tags
    issue_text = issue.text
    # Use regex to extract the number and supplement from the text
    match = re.search(r"(\d+)\s?((suppl)|(spe)|(sup)\w+)?", issue_text.lower())
    if match:
        number = match.group(1)
        supplement = match.group(2)
        if supplement == "":
            supplement = None
        else:
            supplement = supplement.lower()
        return (number, supplement)
    else:
        return ("", "")

def _extract_number_and_supplment_from_issue_element(issue):
    number = issue.split('.')[0]
    supplement = issue.split('.')[1] if '.' in issue else None
    # Handle invalid inputs
    if number.isdigit():
        number = int(number)
    else:
        raise ValueError("Invalid input: Number must be an integer")
    # Handle invalid supplement
    if supplement not in ['Suppl', 'sup']:
        raise ValueError("Invalid input: Supplement must be 'Suppl' or 'sup'")
    return (number, supplement)

def extract_number_and_supplement_from_issue_element(issue):
    """Extrai do conteúdo de <issue>xxxx</issue> os valores number e suppl."""
    # Use regular expressions to extract the number and supplement from the issue element
    match = re.search(r"(?P<number>\d+)(?:\s+su)?pl\s*(?:\d*)", issue)
    if match:
        number = match.group("number")
        supplement = match.group(2) if match.group(2) else 0
        return number, supplement
    else:
        return None, None

def _extract_number_and_supplement_from_issue_element(issue):
    number = None
    suppl = None

    match = re.search(r'(?P<number>\d+) suppl?(?:ement)?(?P<suppl>\d*)?', issue)

    if match:
        number = int(match.group('number'))
        if match.group('suppl') != None:
            suppl = int(match.group('suppl'))

    return number, suppl

