def absorb(self, args):
    new_args = []
    for arg in args:
        if arg in ["A", "B"]:
            new_args.append(arg)
        elif arg == "~A" and new_args[-1] == "A":
            new_args.pop()
        elif arg == "~B" and new_args[-1] == "B":
            new_args.pop()
        else:
            new_args.append(arg)
    return new_args

def absorb(self, args):
    new_args = []
    for arg in args:
        if arg.name == "&" or arg.name == "|":
            symbol = arg.name
            for sub_arg in arg.children:
                if sub_arg.name == "~":
                    continue
                elif sub_arg.name == symbol:
                    new_args.append(sub_arg)
                    break
                else:
                    new_args.append(sub_arg)
        else:
            new_args.append(arg)
    return new_args

def absorb(args: List[Expression]) -> List[Expression]:
    """Given an `args` sequence of expressions, return a new list of expressions applying absorption and negative absorption."""
    result = []
    for arg in args:
        if isinstance(arg, (And, Or)):
            result.extend(absorb(arg.args))
        else:
            result.append(arg)
    return result

def absorb(self, args):
    new_args = []
    for arg in args:
        if arg.op == '&' and arg.right.op == '|' and arg.left == arg.right.left:
            new_args.append(arg.left)
        if arg.op == '|' and arg.right.op == '&' and arg.left == arg.right.left:
            new_args.append(arg.left)
        if arg.op == '&' and arg.right.op == '~' and arg.left == arg.right.right:
            new_args.append(arg.left & arg.right.right)
        if arg.op == '|' and arg.right.op == '~' and arg.left == arg.right.right:
            new_args.append(arg.left | arg.right.right)
    return new_args

