def normalized(self):
    """
    Return a version of this object represented entirely using integer
    values for the relative attributes.

    :return:
        Returns a :class:`dateutil.relativedelta.relativedelta` object.
    """
    # Normalize the values of the relative attributes
    normalized_attrs = {}
    for name, value in self.__dict__.items():
        if name in ('years', 'months', 'days', 'hours', 'minutes', 'seconds'):
            normalized_attrs[name] = int(value)
        elif name in ('year', 'month', 'day', 'weekday', 'hour', 'minute', 'second', 'microsecond'):
            normalized_attrs[name] = int(value + 0.5)
        else:
            normalized_attrs[name] = value
    # Return a new RelativeDelta object with normalized attributes
    return relativedelta(**normalized_attrs)

