def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    if not isinstance(commands, (list, tuple)):
        commands = [commands]

    if not isinstance(args, (list, tuple)):
        args = [args]

    if cwd is not None and not isinstance(cwd, str):
        raise TypeError(f"'cwd' must be a string, got {type(cwd).__name__}")

    if not isinstance(verbose, bool):
        raise TypeError(f"'verbose' must be a boolean, got {type(verbose).__name__}")

    if not isinstance(hide_stderr, bool):
        raise TypeError(f"'hide_stderr' must be a boolean, got {type(hide_stderr).__name__}")

    if env is not None and not isinstance(env, dict):
        raise TypeError(f"'env' must be a dictionary, got {type(env).__name__}")

    if cwd is not None:
        old_cwd = os.getcwd()
        os.chdir(cwd)

    try:
        output = []
        for command in commands:
            try:
                proc = subprocess.Popen(command, args, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env)
                stdout, stderr = proc.communicate(timeout=30)
                if verbose:
                    print(f"Command: {command} {args}")
                    print(f"Stdout: {stdout.decode('utf-8')}")
                    print(f"Stderr: {stderr.decode('utf-8')}")
                output.append((command, stdout.decode('utf-8'), stderr.decode('utf-8')))
            except Exception as e:
                output.append((command, e.__class__.__name__, str(e)))
        return output
    finally:
        if cwd is not None:
            os.chdir(old_cwd)

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    if not commands:
        raise ValueError("No command given")
    if not args:
        raise ValueError("No arguments given")

    cmd = commands.split()
    cmd.append(args)
    cwd = cwd if cwd else os.getcwd()
    env = env if env else os.environ

    if verbose:
        print(f"Running command: {cmd}")

    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            capture_output=True,
            text=True,
            env=env,
        )
    except Exception as e:
        if hide_stderr:
            print(e)
        else:
            print(f"Error running command: {cmd} - {e}")
        return None

    if result.stderr and not hide_stderr:
        print(f"Error running command: {cmd} - {result.stderr}")
        return None

    if result.returncode != 0:
        print(f"Command failed: {cmd} {result.returncode}")
        return None

    return result.stdout

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not commands:
        raise ValueError("Missing command to run")
    if not args:
        args = []
    if cwd:
        current_directory = os.getcwd()
        os.chdir(cwd)
    if env:
        temp_env = os.environ.copy()
        temp_env.update(env)
        env = temp_env
    try:
        if hide_stderr:
            with open(os.devnull, "w") as devnull:
                result = subprocess.run(commands, cwd=cwd, env=env, check=True, stderr=devnull)
        else:
            result = subprocess.run(commands, cwd=cwd, env=env, check=True)
        if verbose:
            print(result.stdout)
        return result.stdout.decode().strip()
    except subprocess.CalledProcessError as e:
        if verbose:
            print(e.stderr)
        raise e
    finally:
        if cwd:
            os.chdir(current_directory)

