def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    num_objects = 0
    good_objects = 0

    # Iterate through each object in the storage hierarchy
    for obj in self.storage:
        num_objects += 1

        # If validate_objects is true, check the object type
        if validate_objects and not isinstance(obj, BaseObject):
            if show_warnings:
                print(f"WARNING: Invalid object {obj} encountered")
            continue

        # If check_digests is true, check the object digest
        if check_digests and not obj.verify_digest():
            if show_warnings:
                print(f"WARNING: Invalid digest for object {obj.name}")
