def next_version(version):
    # Check if version is a valid version number
    if not isinstance(version, str) or not version.isdigit():
        raise TypeError("Invalid version number")

    major, minor, patch = version.split(".")

    # First case: no leading zeroes
    if major.startswith("0") or minor.startswith("0") or patch.startswith("0"):
        major, minor, patch = map(int, (major, minor, patch))
        return f"{major+1}.{minor+1}.{patch+1}"

    # Second case: leading zeroes
    else:
        major, minor, patch = map(int, (major, minor, patch))
        return f"{major+1}.{minor+1}.{patch+1:03}"

def next_version(version):
    if version == 0:
        return 1
    else:
        return version + 1

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if version.count('.') == 2:
        major, minor, patch = version.split('.')
        return f'{major}.{minor}.{int(patch)+1}'
    elif version.count('.') == 1:
        major, minor = version.split('.')
        return f'{major}.{int(minor)+1}.0'
    else:
        raise ValueError('Invalid version number')

def next_version(version):
    major, minor, patch = version.split(".")
    patch = int(patch) + 1
    if patch == 10:
        minor = int(minor) + 1
        patch = 0
    if minor == 10:
        major = int(major) + 1
        minor = 0
    if major == 10:
        raise ValueError("Maximum version reached")
    return f"{major}.{minor}.{patch:02d}"

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    for version_dir in version_dirs:
        if not os.path.isfile(os.path.join(version_dir, "inventory.yml")):
            raise Exception(f"No inventory found for version {version_dir}")

    root_inv_dict = parse_inventory(os.path.join(self.root_dir, "inventory.yml"))
    for version_dir in version_dirs:
        inv_dict = parse_inventory(os.path.join(version_dir, "inventory.yml"))
        version_content_digests = {}
        for file_path, checksum in inv_dict.items():
            if root_inv_dict[file_path] != checksum:
                version_content_digests[file_path] = checksum

    return version_content_digests

def validate_version_inventories(version_dirs):
    version_inventories = {}
    for version_dir in version_dirs:
        version = int(version_dir[1:])
        inventory_file = os.path.join(version_dir, "objects.inv")
        if not os.path.exists(inventory_file):
            raise FileNotFoundError(f"No inventory file found at {inventory_file}")

        with open(inventory_file) as f:
            inventory_records = json.load(f)

            if version not in version_inventories:
                version_inventories[version] = inventory_records
            else:
                root_inventory_records = version_inventories[1]
                for objname in inventory_records:
                    if objname in root_inventory_records and inventory_records[objname] == root_inventory_records[objname]:
                        continue
                    else:
                        raise ValueError(f"Content digest mismatch for object {objname} in version {version}")

    return version_inventories

