def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""

    if not params or not bug_ids:
        raise ValueError("Missing required parameters: params or bug_ids")

    if not isinstance(params, list):
        params = [params]

    if not isinstance(bug_ids, list):
        bug_ids = [bug_ids]

    for p in params:
        if "extra_priority" in p:
            extra_priority = p["extra_priority"]
            del p["extra_priority"]
        else:
            extra_priority = ""

        for bug_id in bug_ids:
            p["bug_id"] = bug_id
            p["extra_priority"] = extra_priority
            yield p

    if extra_priority:
        p["bug_id"] = ""
        p["extra_priority"] = extra_priority
        yield p

