        # If the key does not exist, or the value is a MappingNode, overwrite the value
        if key not in merged_nodes or isinstance(merged_nodes[key], ruamel.yaml.nodes.MappingNode):
            merged_nodes[key] = value
        # If the value is not a MappingNode, and the value for the key is not already a list, make it a list
        elif not isinstance(merged_nodes[key], list):
            merged_nodes[key] = [merged_nodes[key], value]
        # If the value is not a MappingNode, and the value for the key is already a list, add the value to the list
        else:
