    def get_val(node):
        return node[1]

    def is_mapping_node(node):
        return isinstance(get_val(node), ruamel.yaml.nodes.MappingNode)

    def merge_mapping_nodes(old_node, new_node):
        result = deepcopy(old_node)
        for key, val in get_val(new_node).value:
            if key.value in result:
                result[key.value] = merge_nodes(result[key.value], val)
            else:
                result[key.value] = val
        return result

    def merge_nodes(old_node, new_node):
        if is_mapping_node(old_node) and is_mapping_node(new_node):
            return merge_mapping_nodes(old_node, new_node)
        else:
            return new_node

    result = {}
    for node in nodes:
        key = get_key(node)
        if key in result:
            result[key] = merge_nodes(result[key], get_val(node))
        else:
            result[key] = get_val(node)

