def parse_subparser_arguments(unparsed_arguments, subparsers):
    # Initialize empty dicts for parsed arguments and remaining arguments
    parsed_args = {}
    remaining_args = []

    # Check if subparsers dictionary is empty
    if not subparsers:
        return parsed_args, remaining_args

    # Loop through each subparser in the subparsers dictionary
    for subparser_name, subparser in subparsers.items():
        # Try to parse all arguments using the subparser's parse_args() method
        try:
            parsed_args[subparser_name] = subparser.parse_args(unparsed_arguments)
        except SystemExit:
            # If parsing fails, catch the SystemExit exception and continue to the next subparser
            continue
        except:
            # If any other exception is raised, re-raise it
            raise

        # Get the namespace of parsed arguments for the current subparser
        subparser_namespace = parsed_args[subparser_name]

        # Iterate through the unparsed arguments and remove any that were claimed by the subparser
        for arg in subparser_namespace._get_positional_args():
            if arg in unparsed_arguments:
                unparsed_arguments.remove(arg)

    # Return the parsed arguments and any remaining arguments
    return parsed_args, unparsed_arguments

