def deep_merge_nodes(nodes):
    """Deep merges any node values corresponding to duplicate keys and returns the result.
    Colliding keys with non-MappingNode values (e.g., integers or strings) are either
    replaced or used as-is, depending on how they're encountered first.

    Args:
        nodes (list[(ruamel.yaml.nodes.ScalarNode, ruamel.yaml.nodes.Node)]): List of tuples
            consisting of a ScalarNode as the key and a Node as the value.

    Returns:
        list[(ruamel.yaml.nodes.ScalarNode, ruamel.yaml.nodes.Node)]: List of tuples
            consisting of a ScalarNode as the key and a Node as the value.
    """
    # Mapping of key: value pairs
    mapping = defaultdict(list)
    for n in nodes:
        key, value = n
        if isinstance(value, MappingNode):
            for k, v in value.value:
                if k in mapping[key]:
                    if isinstance(mapping[key], MappingNode):
                        mapping[key].value[mapping[key].value.index(k)] = v
                    else:
                        mapping[key] = v
                else:
                    mapping[key].append(v)
        else:
            mapping[key] = value
    return [(ScalarNode(tag='tag:yaml.org,2002:str', value=k), MappingNode(tag='tag:yaml.org,2002:map', value=v)) for k, v in mapping.items()]

def deep_merge_nodes(nodes):
    from ruamel.yaml.nodes import ScalarNode, MappingNode

    def _merge_mapping_nodes(m1, m2):
        for key in m2:
            if key in m1:
                if isinstance(m1[key], MappingNode) and isinstance(m2[key], MappingNode):
                    _merge_mapping_nodes(m1[key], m2[key])
                else:
                    m1[key] = m2[key]
            else:
                m1[key] = m2[key]

    # create a dictionary with the nodes
    node_dict = {}
    for node in nodes:
        if node.key not in node_dict:
            if isinstance(node.value, MappingNode):
                node_dict[node.key] = deepcopy(node.value)
            else:
                node_dict[node.key] = node.value
        else:
            if isinstance(node_dict[node.key], MappingNode) and isinstance(node.value, MappingNode):
                _merge_mapping_nodes(node_dict[node.key], node.value)
            else:
                node_dict[node.key] = node.value

    # convert the dictionary back to a list of tuples
    return [
        (ScalarNode(tag='tag:yaml.org,2002:str', value=key), MappingNode(tag='tag:yaml.org,2002:map', value=value))
        for key, value in node_dict.items()
    ]

def deep_merge_nodes(nodes):
    for i, node in enumerate(nodes):
        key, value = node
        if key in [n[0] for n in nodes[i+1:]]:
            for n in nodes[i+1:]:
                if key == n[0]:
                    value.value.merge(n[1].value)
                    nodes = nodes[:i] + [(key,value)] + nodes[i+2:]
                    break
        else:
            nodes = nodes[:i] + [(key,value)] + nodes[i+1:]
    return nodes

