def size_to_bytes(size: str) -> int:
    bytes_suffix = {
        "B": 1,
        "K": 1024,
        "M": 1024**2,
        "G": 1024**3,
        "T": 1024**4,
        "P": 1024**5,
        "E": 1024**6,
        "Z": 1024**7,
        "Y": 1024**8,
    }

    size_num = size[:-1]
    size_unit = size[-1]

    try:
        return int(float(size_num) * bytes_suffix[size_unit])
    except KeyError:
        raise ValueError(f"Invalid suffix '{size_unit}'")
    except ValueError:
        raise ValueError(f"Invalid size string '{size}'")

def size_to_bytes(size: str) -> int:
    bytes = {"k": 1000, "m": 1000 ** 2}
    if size.endswith("k"):
        return int(size[:-1]) * bytes["k"]
    elif size.endswith("m"):
        return int(size[:-1]) * bytes["m"]
    return int(size)

def size_to_bytes(size: str) -> int:
    size = size.lower()
    num = float(size[:-1])
    unit = size[-1]
    if unit == 'k':
        return num * 1000
    elif unit == 'm':
        return num * 1000000
    elif unit == 'g':
        return num * 1000000000
    return num

def size_to_bytes(size: str) -> int:
    size = size.upper()
    size_num = size[:-1]
    size_suffix = size[-1]
    if size_suffix not in ["B", "K", "M", "G", "T"]:
        raise ValueError("Invalid input size")
    if size_suffix == "B":
        size_num = float(size_num)
    elif size_suffix == "K":
        size_num = float(size_num) * 1000
    elif size_suffix == "M":
        size_num = float(size_num) * 1000000
    elif size_suffix == "G":
        size_num = float(size_num) * 1000000000
    else:
        size_num = float(size_num) * 1000000000000
    return int(size_num)

def size_to_bytes(size: str) -> int:
    try:
        return int(size)
    except ValueError:
        size_str, unit = size[:-1], size[-1]
        if unit not in ["B", "K", "M", "G", "T"]:
            raise ValueError("Invalid input")
        return int(size_str) * {"B": 1, "K": 1000, "M": 1000000, "G": 1000000000, "T": 1000000000000}[unit]
    except KeyError:
        pass
    raise ValueError("Invalid input")

