def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not isinstance(number, int):
        raise TypeError("'number' must be an integer")
    if not isinstance(alphabet, list) and not all(isinstance(c, str) for c in alphabet):
        raise TypeError("'alphabet' must be a list of strings")
    if padding is not None and not isinstance(padding, int):
        raise TypeError("'padding' must be an integer")

    if number < 0:
        raise ValueError("'number' must be non-negative")
    if len(alphabet) == 0:
        raise ValueError("'alphabet' must have at least one character")
    if padding is not None and padding < 0:
        raise ValueError("'padding' must be non-negative")

    result = []
    while number > 0:
        result.append(alphabet[number % len(alphabet)])
        number //= len(alphabet)
    if padding is not None:
        result += [0 for _ in range(padding)]
    result.reverse()
    return "".join(result)

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    result = ""
    while number > 0:
        digit = number % len(alphabet)
        result = alphabet[digit] + result
        number = number // len(alphabet)
    if padding:
        result = padding * "0" + result
    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not isinstance(number, int):
        raise ValueError("number must be an integer")
    if not isinstance(alphabet, list) or len(alphabet) == 0:
        raise ValueError("alphabet must be a non-empty list of strings")
    if padding is not None and not isinstance(padding, int):
        raise ValueError("padding must be an integer or None")

    # Convert the number to a string using the given alphabet
    number_str = ""
    while number > 0:
        number_str = alphabet[number % len(alphabet)] + number_str
        number //= len(alphabet)

    # Pad the resulting string with zeros if necessary
    if padding is not None and len(number_str) < padding:
        number_str = "0" * (padding - len(number_str)) + number_str

    return number_str

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int):
        raise TypeError("number must be an integer")
    if not isinstance(alphabet, (list, tuple)):
        raise TypeError("alphabet must be a list or tuple")
    if not all(isinstance(c, str) for c in alphabet):
        raise TypeError("all elements in alphabet must be strings")
    if padding is not None and not isinstance(padding, int):
        raise TypeError("padding must be an integer")

    res = ""
    while number > 0:
        res = alphabet[number % len(alphabet)] + res
        number //= len(alphabet)

    if padding is not None:
        res = res.zfill(padding)

    return res

