def string_to_int(string: str, alphabet: List[str]) -> int:
    if not isinstance(string, str):
        raise ValueError("Input string must be a string")
    if not isinstance(alphabet, list):
        raise ValueError("Alphabet must be a list")
    if len(string) != len(alphabet):
        raise ValueError("String and alphabet must be of equal length")

    base = len(alphabet)
    result = 0
    for i, c in enumerate(reversed(string)):
        index = alphabet.index(c)
        if index >= base:
            raise ValueError(f"Invalid character {c} at position {len(string) - i}")
        result += index * base ** i

    return result

def string_to_int(string: str, alphabet: List[str]) -> int:
    if not string:
        raise ValueError("string must be a non-empty string")
    if not alphabet or not isinstance(alphabet, list):
        raise ValueError("alphabet must be a non-empty list of strings")
    if any(not isinstance(char, str) for char in alphabet):
        raise ValueError("alphabet must contain only strings")

    result = 0
    for i, char in enumerate(reversed(string)):
        index = alphabet.index(char)
        result += index * (len(alphabet) ** i)

    return result

def string_to_int(string: str, alphabet: List[str]) -> int:
    alphabet_size = len(alphabet)
    num = 0
    for i, char in enumerate(reversed(string)):
        num += alphabet.index(char) * (alphabet_size ** i)
    return num

def string_to_int(string: str, alphabet: List[str]) -> int:
    total = 0
    for i, letter in enumerate(string):
        if letter not in alphabet:
            raise ValueError(f"Invalid letter {letter} in string {string}")
        total += alphabet.index(letter) * (len(alphabet) ** (len(string) - i - 1))
    return total

