private static string[] Split(string s, string platform = "this")
{
    // Validate input parameters
    if (platform != "this" && platform != "1" && platform != "0")
        throw new ArgumentException("The value of `platform` must be 'this', '1', or '0'.");

    // Choose the appropriate splitting algorithm based on the current platform
    Func<string, string[]> splitter = platform switch
    {
        "this" => platform switch
        {
            "linux" => (string str) => str.Split(' ', StringSplitOptions.RemoveEmptyEntries),
            "windows" => (string str) => str.Split(' ', StringSplitOptions.RemoveEmptyEntries),
            _ => throw new ArgumentException($"Unsupported platform: {platform}")
        },
        "1" => (string str) => str.Split(' ', StringSplitOptions.RemoveEmptyEntries),
        "0" => (string str) => str.Split(' ', StringSplitOptions.RemoveEmptyEntries),
        _ => throw new ArgumentException($"Unknown platform: {platform}")
    };

    // Split the input string using the chosen algorithm
    return splitter(s);
}

def split(s, platform='this'):
    """Splits a string into a list of tokens using a variant of shlex.split()
    that is safe for use on the command-line.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)

    Returns: list of tokens
    """

    if platform == 'this':
        platform = get_platform()

    if platform == 1:
        return re.findall(r'(?:\([^()]*\)|[^\s()]+)+', s)
    elif platform == 0:
        return re.findall(r'(?:\".*?\"|[^"\s]+)+', s)
    else:
        raise ValueError(f'Invalid platform: {platform!r}')

def split(s, platform='this'):
    if platform == 'this':
        if sys.platform == 'win32':
            pattern = r' +'
        else:
            pattern = r'\s+'
    elif platform == 1:
        pattern = r"['\"]?([^'\"\s]*(\\['\"]|[^'\"]*)*)+['\"]?"
    elif platform == 0:
        pattern = r' +'
    else:
        raise ValueError('Invalid value for "platform" argument')
    return re.split(pattern, s)

