def make_find_paths(find_paths):
        '''
        Given a sequence of path fragments or patterns as passed to `--find`, transform all path
        fragments into glob patterns. Pass through existing patterns untouched.

        For example, given find_paths of:

          ['foo.txt', 'pp:root/somedir']

        ... transform that into:

          ['sh:**/*foo.txt*/**', 'pp:root/somedir']
        '''
        new_paths = []
        for path in find_paths:
            if re.match(r'[A-Za-z]:\\', path):
                new_paths.append(path)
            else:
                if path.startswith('pp:') or path.startswith('sh:'):
                    new_paths.append(path)
                else:
                    new_paths.append('sh:**/*' + path + '*/**')
        return new_paths

def make_find_paths(find_paths):
    # transform each path fragment into a glob pattern
    find_paths = [re.search('out\d+', path) for path in find_paths]

def find_paths(find_params):
    patterns = []
    for path in find_paths:
        match = re.match(r'(?:pp|sh)(:root/.*)', path)
        if match is not None:
            patterns.append(match.group(1))
        else:
            patterns.append(f'sh:**/*{path}*/**')
    return patterns

