def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    if not rendered_config or not config_filename:
        raise ValueError("Both rendered_config and config_filename must be specified")
    if not overwrite and os.path.exists(config_filename):
        return False
    directory = os.path.dirname(config_filename)
    if not os.path.exists(directory):
        os.makedirs(directory, mode=mode, exist_ok=True)
    with open(config_filename, "w", newline="") as f:
        f.write(rendered_config)
    return True

