def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    """Given a target config filename and rendered config YAML, write it out to file. Create any containing directories as needed. But if the file already exists and overwrite is False, abort before writing anything."""
    try:
        # Check if the file already exists and if overwrite is True
        if os.path.exists(config_filename) and not overwrite:
            raise FileExistsError(f"The file {config_filename} already exists and overwrite is False.")
        # Create containing directories if needed
        if os.path.dirname(config_filename):
            os.makedirs(os.path.dirname(config_filename), exist_ok=True)
        # Write out the rendered config to the file
        with open(config_filename, "w", mode) as f:
            f.write(rendered_config.dump())
    except FileExistsError as e:
        print(e)
        raise
    except Exception as e:
        print(e)
        raise

def oneline(script, seperator="&&"):
    lines = textwrap.dedent(script).strip().split('\n')
    return seperator.join(lines).lstrip()

def subprocess_run_helper(func, *args, timeout, extra_env=None):
    cmd = [sys.executable, '-m', 'funcy.subprocess_run']
    cmd.extend(args)
    env = os.environ.copy()
    env.update(extra_env or {})
    try:
        output = subprocess.run(cmd, timeout=timeout, env=env, check=True)
    except subprocess.CalledProcessError as e:
        if e.returncode == 126:
            raise ValueError('The function could not be imported.')
        elif e.returncode == 127:
            raise RuntimeError('The command could not be found.')
        else:
            raise RuntimeError('An unexpected error occurred.')
    return output.stdout.decode('ascii')

def subprocess_run_helper(func, *args, timeout, extra_env=None):
    try:
        process = subprocess.run(
            [sys.executable, "-u", "-c", func],
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            env=extra_env,
        )
        stdout, stderr = process.communicate(timeout=timeout)
        if process.returncode == 0:
            return stdout, stderr
        else:
            raise RuntimeError("Error running function in subprocess: " + stderr.decode())
    except Exception as e:
        raise RuntimeError("Error running function in subprocess: " + str(e))

def _resolve_string(matcher):
    name = matcher.group(1)
    default = matcher.group(2)
    value = os.getenv(name)
    if value is None:
        if default is not None:
           return default
        else:
            raise RuntimeError(f"Variable {name} is not defined in the environment and no default value was provided.")
    else:
        return value

def resolve_string(matcher):
    if not matcher or not isinstance(matcher, str):
        raise ValueError("matcher must be a non-empty string")

    matcher_parts = matcher.split('@')
    if len(matcher_parts) != 2:
        raise ValueError("matcher must be in the format 'name@default_value'")

    name, default_value = matcher_parts
    value = os.environ.get(name)
    if value is None:
        if default_value is not None:
            return default_value
        raise ValueError(f"variable '{name}' is not defined in the environment")

    return value

This method takes a string `matcher` as input, which is expected to be in the format `'name@default_value'`. It first splits the matcher by the `'@'` character to get the name and default value. It then checks if the variable is defined in the environment. If it is, it returns the value for that variable. If it is not, it returns the default value if it is provided. If the variable is not defined and there is no default value, it raises a `ValueError`. The method also raises a `ValueError` if the `matcher` parameter is empty or not a string.

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value. If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Use try-except block to handle potential KeyError when trying to access environment variable
    try:
        return os.environ[matcher.name]
    except KeyError:
        # Check if default value is provided
        if matcher.default is not None:
            return matcher.default
        else:
            # Raise Error if variable is not defined in environment and no default value is provided
            raise ValueError(f"{matcher.name} is not defined in environment and no default value provided")

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    if image_href is None or not isinstance(image_href, str):
        raise ValueError("image_href must be a non-empty string")

    url = urllib.parse.urlparse(image_href)

    image_id = url.path.lstrip("/")
    netloc = url.hostname
    use_ssl = url.scheme == "https"

    return (image_id, netloc, use_ssl)

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:

    """
    try:
        url = urllib.parse.urlparse(image_href)
        if url.scheme == "http":
            netloc = url.netloc
            use_ssl = False
        elif url.scheme == "https":
            netloc = url.netloc
            use_ssl = True
        else:
            raise ValueError("Invalid scheme: " + url.scheme)
        image_id = url.path.split("/")[-1]
        return image_id, netloc, use_ssl
    except ValueError as e:
        raise ValueError(f"Invalid image href: {image_href}") from e

