def get_pattern(pattern, strip=True):
    try:
        pattern = re.compile(pattern)
    except Exception as e:
        raise ValueError(f"Invalid pattern: {pattern}. {e}")
    if strip:
        pattern = pattern.strip()
    return pattern

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern
    """
    if pattern == "":
        raise ValueError("Empty pattern is not allowed")
    if not isinstance(strip, bool):
        raise TypeError("Strip must be a boolean value")
    if re.match(r"\A#.*?\Z", pattern):
        pattern = re.sub(r"\A#*", "", pattern)

    pattern = re.compile(pattern, re.IGNORECASE)
    return pattern

def convert_string_to_regex_pattern(string: str, strip: bool = True) -> str:
    """
    This method converts the given string to a regex pattern.
    :param string: The string to convert to a regex pattern.
    :param strip: Whether to remove leading and trailing whitespace from the input string before converting to a regex pattern.
    :return: A regex pattern constructed from the given string.
    """
    if strip:
        string = string.strip()
    return re.escape(string)

def get_pattern(pattern, strip=True):
    """
    Converts the given string to regex pattern
    """
    if pattern is None:
        raise ValueError("pattern cannot be None")
    pattern_str = str(pattern)
    if strip:
        pattern_str = pattern_str.strip()
    if not pattern_str:
        raise ValueError("pattern cannot be empty")
    return re.compile(pattern_str)

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, (list, tuple)):
        commands = [commands]
    if not isinstance(args, (list, tuple)):
        args = [args]
    if cwd is None:
        cwd = os.getcwd()
    try:
        process = subprocess.Popen(commands, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env)
        stdout, stderr = process.communicate(args)
        if verbose:
            print(stdout, stderr)
        if hide_stderr and stderr != '':
            print(stdout)
        return stdout if not hide_stderr else None
    except OSError as e:
        raise Exception(f"Failed to run command {commands} with args {args}. The error is {e.args}") from e

