    if not commands:
        raise ValueError("commands cannot be empty")
    if not args:
        raise ValueError("args cannot be empty")
    if cwd is not None and not os.path.isdir(cwd):
        raise ValueError("cwd must be a valid directory")
    if hide_stderr:
        stdout = subprocess.PIPE
    elif verbose:
        stdout = None
    else:
        stdout = subprocess.DEVNULL
    stderr = None if hide_stderr else subprocess.STDOUT
    try:
        proc = subprocess.run(commands, args, check=True, stdout=stdout, stderr=stderr, cwd=cwd, env=env)
    except subprocess.CalledProcessError as e:
        raise e

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if isinstance(commands, list):
        commands = map(str, commands)
    elif isinstance(commands, str):
        commands = (commands,)
    else:
        raise ValueError(f"Commands must be a list or a string. Got {type(commands)}.")
    if args is None:
        args = []
    elif isinstance(args, list):
        args = map(str, args)
    elif isinstance(args, str):
        args = (args,)
    else:
        raise ValueError(f"Args must be a list or a string. Got {type(args)}.")
    if cwd is not None and not isinstance(cwd, str):
        raise ValueError("Cwd must be a string or None.")
    if env is not None and not isinstance(env, dict):
        raise ValueError("Env must be a dict or None.")
    proc = subprocess.Popen(
        [commands] + args,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE if hide_stderr else None,
        cwd=cwd,
        env=env,
        universal_newlines=True,
        bufsize=1,
    )
    if verbose:
        for line in proc.stdout:
            print(line, end="", flush=True)
    stdout, stderr = proc.communicate()
    if proc.returncode != 0:
        raise subprocess.CalledProcessError(proc.returncode, [commands] + args, stdout, stderr)
    if stderr and not hide_stderr:
        print(stderr, flush=True)
    return stdout.rstrip()

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    # Initialize command and arguments
    cmd = commands.split()[0]
    args = commands.split()[1:] + args

    # Optional: set the working directory
    if cwd is not None:
        os.chdir(cwd)

    # Initialize environment variables
    if env is not None:
        for key, val in env.items():
            os.environ[key] = val

    # Call the command
    try:
        output = subprocess.check_output(cmd, args, cwd=cwd, universal_newlines=True, stderr=subprocess.STDOUT if hide_stderr else None)
        if verbose:
            print("Ran command:", cmd, args)
            print(output)
        return output
    except subprocess.CalledProcessError as e:
        return e.output

