def find_roots(graph, prop, roots=None):
    if roots is None:
        roots = set()
    for s, p, o in graph:
        if s == p and p == o:
            roots.add(s)
        elif s == p and o not in roots:
            roots.add(o)
        elif o not in roots and o not in roots:
            roots.add(o)
    return roots

def find_roots(graph, prop, roots=None):
    if roots is None:
        roots = set()

    for node in graph.nodes:
        if not graph.has_node(node):
            continue

        for child in graph.successors(node):
            if child in roots:
                continue

            if graph.get_edge_data(child, prop):
                roots.add(child)
                find_roots(graph, prop, roots)

    return roots

def find_roots(graph, prop, roots=None):
    if roots is None:
        roots = set()
    for s, p, o in graph.triples((None, prop, None)):
        if s not in roots:
            roots.add(s)
            roots.update(find_roots(graph, prop, roots))
    return roots

def find_roots(graph: Graph, prop: URIRef, roots: Optional[Set[Node]] = None) -> Set[Node]:
    if roots is None:
        roots = set()
    for s, p, o in graph:
        if p == prop and o not in roots:
            roots.add(o)
            find_roots(graph, prop, roots)
    return roots

