def _dump_string(obj, dumper=None):
    if dumper is None:
        dumper = yaml.dumper.SafeDumper

    class EncodingDumper(dumper):
        def encode_mapping_node(self, node):
            return yaml.dumper.SafeDumper.encode_mapping_node(self, node)

        def encode_unicode(self, node):
            return node.encode('utf-8')

    result = yaml.compose(obj, Loader=EncodingDumper)
    return yaml.dump(result, Dumper=EncodingDumper)

def dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    if sys.version_info >= (3, 0):
        encoder = yaml.SafeDumper
        return encoder.represent_unicode(obj)
    else:
        encoder = yaml.Emitter
        return encoder.represent(obj)

