def load_configurations(config_filenames, overrides=None, resolve_env=True):
    # Initialize empty dictionaries to store the configuration names and parsed configurations
    parsed_configs = {}
    parse_errors = []

    # Iterate over the sequence of configuration filenames
    for config_file in config_filenames:
        # Try to parse the configuration file
        try:
            # If the overrides dictionary is provided, update the configuration with the provided values
            if overrides is not None:
                parser = configparser.ConfigParser(overrides)
            else:
                parser = configparser.ConfigParser()
            parser.read(config_file)

            # Update the parsed configurations dictionary with the parsed configuration
            parsed_configs[config_file] = parser
        except configparser.MissingSectionHeaderError:
            # If the configuration file has a missing section header, log a warning
            warning = logging.warning(f"Configuration file '{config_file}' has a missing section header")
            parse_errors.append(warning)
        except configparser.ParsingError as e:
            # If the configuration file has a parsing error, log a fatal error
            error = logging.error(f"Fatal parsing error in configuration file '{config_file}': {e}")
            parse_errors.append(error)

    return parsed_configs, parse_errors

