def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    configs = {}
    errors = []
    for filename in config_filenames:
        path = os.path.join(os.path.dirname(__file__), filename)
        try:
            with open(path) as f:
                data = json.load(f)
                configs[filename] = data
        except IOError as e:
            logging.error("Could not open configuration file: {}".format(filename))
            errors.append(e)
        except ValueError as e:
            logging.error("Invalid configuration file: {}".format(filename))
            errors.append(e)
        except KeyError as e:
            logging.error("Configuration file is missing a required key: {}".format(filename))
            errors.append(e)
    if overrides:
        for filename, data in overrides.items():
            configs[filename] = data
    if resolve_env:
        for filename, data in configs.items():
            for key, value in data.items():
                if isinstance(value, str) and value.startswith("$"):
                    var = value.lstrip("$")
                    if var in os.environ:
                        configs[filename][key] = os.environ[var]
                    else:
                        logging.warning("Environment variable {} not set".format(var))
                        errors.append(logging.LogRecord("env", "WARNING", 0, filename, "Environment variable {} not set".format(var)))
    return configs, errors

