def load_configurations(config_filenames, overrides=None, resolve_env=True):
    configurations = {}
    log_records = []
    for config_filename in config_filenames:
        try:
            with open(config_filename, "r") as f:
                config = json.load(f)
                if overrides:
                    config.update(overrides)
                if resolve_env:
                    config = resolve_env_vars(config)
                configurations[config_filename] = config
        except FileNotFoundError:
            log_records.append(
                logging.LogRecord(
                    logger=logging.getLogger(__name__),
                    loglevel=ERROR,
                    msg=f"Configuration file not found: {config_filename}",
                )
            )
        except ValueError:
            log_records.append(
                logging.LogRecord(
                    logger=logging.getLogger(__name__),
                    loglevel=ERROR,
                    msg=f"Error parsing configuration file: {config_filename}",
                )
            )
    return configurations, log_records

