classmethod_protocol_handlers(cls, protocol_version=None):
    if protocol_version is None:
        return {
            protocol_version: handler_cls
            for protocol_version, handler_cls in cls._protocol_handlers.items()
            if protocol_version <= cls._max_supported_protocol_version
        }
    else:
        if not isinstance(protocol_version, tuple):
            raise TypeError("Invalid protocol version")
        if protocol_version not in cls._protocol_handlers:
            raise ValueError("Unsupported protocol version")
        return {protocol_version: cls._protocol_handlers[protocol_version]}

def protocol_handlers(cls, protocol_version=None):
        handlers = {
            (3, 5): cls._protocol_handler_3_5,
            (4, 0): cls._protocol_handler_4_0,
        }
        if protocol_version:
            if not isinstance(protocol_version, tuple):
                raise TypeError("Protocol version must be passed as a tuple")
            version = protocol_version
