        if not tentative:
            assert iface.providedBy(candidate)
        for method_name, expected_sig in iface.namesAndDescriptions(lambda m: not m.isAttr):
            actual_sig = getattr(candidate, method_name)(getInitialArguments(candidate))
            assert method_signatures_match(expected_sig, actual_sig)
        for attribute_name in iface.namesAndDescriptions(lambda m: m.isAttr):
            assert hasattr(candidate, attribute_name)
    except Exception as e:
        raise Invalid(e)
    return True

def _verify(iface, candidate, tentative=False, vtype=None):
    try:
        if not tentative:
            if not iface.providedBy(candidate):
                raise zope.interface.Invalid(f"{candidate} does not provide interface {iface}")
        for method in candidate.classmro().keys():
            if method.resolve() in iface.names():
                if not hasattr(candidate, method.name):
                    raise zope.interface.Invalid(f"{candidate} is missing method {method}")
                if vtype and candidate.classmro()[method.name].__annotations__[vtype]:
                    raise zope.interface.Invalid(f"Method {method} does not annotate with {vtype}")
        for attribute in iface.names():
            if not hasattr(candidate, attribute):
                raise zope.interface.Invalid(f"{candidate} is missing attribute {attribute}")
            if vtype and not candidate.classmro()[attribute].__annotations__[vtype]:
                raise zope.interface.Invalid(f"Attribute {attribute} does not annotate with {vtype}")
        return True
    except Exception as e:
        raise zope.interface.Invalid(str(e))

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using iface.providedBy (unless tentative is True,
      in which case this step is skipped). This means that the candidate's class
      declares that it implements the interface,
      or the candidate itself declares that it provides
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.
    """
    try:
        provided = iface.providedBy(candidate)
    except Invalid:
        if provided is None and tentative is False:
            raise Invalid("Could not determine that %s provides %s" % (candidate, iface))
    missing_methods = []
    for name, spec in iface._implementedBy.items():
        try:
            meth = getattr(candidate, name)
        except AttributeError:
            missing_methods.append(name)
        else:
            if not meth.__signature__ == spec.meth.__signature__:
                raise Invalid(
                    "The method %s does not match the specification for the attribute %s"
                    % (name, spec.name)
                )
    missing_attrs = []
    for name, spec in iface._providedBy.items():
        try:
            attr = getattr(candidate, name)
        except AttributeError:
            missing_attrs.append(name)
        else:
            if not attr.__signature__ == spec.attr.__signature__:
                raise Invalid(
                    "The attribute %s does not match the specification for the attribute %s"
                    % (name, spec.name)
                )
    if missing_attrs or missing_methods:
        raise Invalid(
            "The object %s does not provide the required attributes or methods:\n"
            "Missing methods: %s\n"
            "Missing attributes: %s" % (candidate, missing_methods, missing_attrs)
        )
    return True

