    providedBy = getattr(candidate, "providedBy", None)
    if not tentative and not (providedBy is None or iface in providedBy):
        raise zope.interface.Invalid("Candidate does not specify that it provides the interface")

    providedBy = getattr(candidate, "provides", None)
    if not tentative and not (providedBy is None or iface in providedBy):
        raise zope.interface.Invalid("Candidate does not specify that it provides the interface")

    for method in getattr(iface, "methods", []):
