            raise zope.interface.Invalid(f"Candidate does not define method `{method}`")
        elif not getattr(candidate, method) == getattr(iface, method):
            raise zope.interface.Invalid(f"Method signature for `{method}` does not match interface")

    for attribute in getattr(iface, "attributes", []):
        if not hasattr(candidate, attribute):
            raise zope.interface.Invalid(f"Candidate does not define attribute `{attribute}`")
        elif not getattr(candidate, attribute) == getattr(iface, attribute):
