            raise Invalid("Candidate does not claim to provide the interface")
        for attr in iface.attributes():
            if attr.name not in candidate.__dict__:
                raise Invalid("Candidate does not define required attribute '{}'".format(attr.name))
            attrValue = getattr(candidate, attr.name)
            if type(attrValue) != attr.type:
                raise Invalid("Attribute '{}' defined with an incorrect type. Expected {}, got {}".format(attr.name, attr.type, type(attrValue)))
        for method in iface.methods():
            if method.name not in candidate.__dict__:
                raise Invalid("Candidate does not define required method '{}'".format(method.name))
            methodValue = getattr(candidate, method.name)
            args = tuple(argspec.args for argspec in method.arguments)
            if args != methodValue.args:
                raise Invalid("Method '{}' defined with an incorrect signature. Expected {}, got {}".format(method.name, args, methodValue.args))
    except Invalid:
        return False
    return True

