    """
    Verify that the *candidate* might correctly provide *iface*.
    :param iface: The interface to check.
    :type iface: str
    :param candidate: The object to check.
    :type candidate: object
    :param tentative: Whether the verification is tentative.
    :type tentative: bool
    :return: Whether the *candidate* might correctly provide *iface*.
    :rtype: bool
    """

    if not isinstance(iface, str):
        raise TypeError("iface must be a string")
    if not isinstance(candidate, object):
        raise TypeError("candidate must be an object")
    if not isinstance(tentative, bool):
        raise TypeError("tentative must be a boolean")

    if not hasattr(candidate, iface):
        return False

    if not repr(getattr(candidate, iface)).startswith("class_"):
        return False

    if tentative is True:
        return issubclass(getattr(candidate, iface), type)

    return isinstance(getattr(candidate, iface), type)

