        bases (list): List of base classes
        explicit_mc (type, optional): Explicit metaclass

    Returns:
        type: Metaclass

    """
    if explicit_mc is not None:
        return explicit_mc
    elif len(bases) == 1:
        return type(bases[0])
    else:
        for base in bases:
            if type(base) is not 'type':
                return type(base)

