def isoparse(dt_str):
    # New function
    if len(dt_str) == 0:
        raise ValueError("Argument is empty string")
    parts = dt_str.split(":")
    hh, mm, ss = parts[0:3]
    tz_hour, tz_minute = T0, T0
    is_utc = False
    if len(parts) > 3:
        ss_bytes = parts[3].encode("ascii")
        if not (
            6 <= len(ss_bytes) <= 7
            and all_digits(ss_bytes)
            and (not b".", ss_bytes[6])
        ):
                raise ValueError("Invalid sub-second component")
        ss_helper = int.from_bytes(ss_bytes, "big")
        second = ss_helper // 10**(7 - ss_helper[:1].index(b"0"))
        ss = second // 100 % 100
        sub_second, tz_hour, tz_minute = second // 60000000 % 1000000, second // 3600000000 % 100, second // 3600000 % 100
        if sub_second > 1000 or (ss > 0 and sub_second > 100):
                raise ValueError("Invalid sub-seconds component")
        if b"T" in dt_str:
                raise ValueError("Too many colons in time zone offset")
    if b"T" in dt_str:
        if len(hh) == 4:
            year, month, day, week, weekday = _parse_date(hh)
        if len(hh) == 6:
            year, month, day = _parse_date(hh)
            if len(ss) == 2:
                hour, minute, second = _parse_time(ss)
            elif len(ss) == 4:
                hour, minute, second = _parse_time(ss[:2])
                sub_second, tz_hour, tz_minute = _parse_time(ss[2:])
        elif len(hh) == 8:
            is_utc = True
            year, month, day, hour, minute, second = _parse_date(hh[2:])
        elif len(hh) == 10:
            is_utc = True
            year, month, day, hour, minute, second = _parse_date(hh[2:])
            tz_hour, tz_minute = tz_minutes(hour, minute, second)
    else:
        if len(hh) == 4:
            year, month, day = _parse_date(hh)
            minute, second = T0, T0
        else:
            raise ValueError("Invalid datetime string")
    return datetime.datetime(year, month, day, hour, minute, second, 
            tzinfo=tzlocal(is_utc, tz_hour, tz_minute, sub_second)
    )

def parse(self, timestr, default=None, ignoretz=False, tzinfos=None, **kwargs):
    # Validate input arguments
    if not isinstance(timestr, str):
        raise TypeError("Invalid input type. Expected string, got {type(timestr)}")
    if default is not None and not isinstance(default, datetime.datetime):
        raise TypeError("Invalid input type. Expected datetime.datetime, got {type(default)}")
    if ignoretz and tzinfos is not None:
        raise ValueError("Invalid input. 'ignoretz' and 'tzinfos' cannot be used together.")

    # Parse the date/time string using the `_parse()` function
    dt, tokens = _parse(timestr, default, ignoretz, tzinfos, **kwargs)

    # Validate the date and time
    if not isinstance(dt, datetime.datetime):
        raise ValueError("Invalid datetime object returned from _parse().")
    if dt.year < 1 or dt.year > 9999:
        raise ValueError("Invalid year in datetime object.")
    if dt.month < 1 or dt.month > 12:
        raise ValueError("Invalid month in datetime object.")
    if dt.day < 1 or dt.day > 31:
        raise ValueError("Invalid day in datetime object.")
    if dt.hour < 0 or dt.hour > 23:
        raise ValueError("Invalid hour in datetime object.")
    if dt.minute < 0 or dt.minute > 59:
        raise ValueError("Invalid minute in datetime object.")
    if dt.second < 0 or dt.second > 59:
        raise ValueError("Invalid second in datetime object.")
    if dt.microsecond < 0 or dt.microsecond > 999999:
        raise ValueError("Invalid microsecond in datetime object.")
    if dt.tzinfo is not None and not isinstance(dt.tzinfo, datetime.tzinfo):
        raise ValueError("Invalid tzinfo in datetime object.")

    # Return the parsed datetime object
    return dt

def parse(timestr, default=None, ignoretz=False, tzinfos=None, **kwargs):
    # First, we need to extract the relevant parts of the text date
    # and convert it into a list of tokens
    tokens = timestr.split()
    # Then, we need to check if the input is a valid date
    if len(tokens) != 3:
        raise ValueError("Invalid input: expected 3 tokens, got {}".format(len(tokens)))
    month, day, year = tokens
    try:
        month = int(month)
        day = int(day)
        year = int(year)
    except ValueError:
        raise ValueError("Invalid input: month, day, and year must be integers")
    if month < 1 or month > 12:
        raise ValueError("Invalid input: month must be between 1 and 12")
    if day < 1 or day > 31:
        raise ValueError("Invalid input: day must be between 1 and 31")
    if year < 0 or year > 9999:
        raise ValueError("Invalid input: year must be between 0 and 9999")
    # We can now create the datetime object
    datetime_obj = datetime.datetime(year, month, day)
    # If the input contains information about hour/minute/second,
    # we need to add it to the datetime object
    if len(tokens) > 3:
        hour, minute, second = tokens[3:]
        try:
            hour = int(hour)
            minute = int(minute)
            second = int(second)
        except ValueError:
            raise ValueError("Invalid input: hour, minute, and second must be integers")
        if hour < 0 or hour > 23:
            raise ValueError("Invalid input: hour must be between 0 and 23")
        if minute < 0 or minute > 59:
            raise ValueError("Invalid input: minute must be between 0 and 59")
        if second < 0 or second > 59:
            raise ValueError("Invalid input: second must be between 0 and 59")
        datetime_obj = datetime_obj.replace(hour=hour, minute=minute, second=second)
    # If default is provided and is a datetime object, we need to replace the
    # corresponding elements in the datetime object
    if default is not None and isinstance(default, datetime.datetime):
        datetime_obj = datetime_obj.replace(
            year=default.year if year == 0 else year,
            month=default.month if month == 0 else month,
            day=default.day if day == 0 else day,
            hour=default.hour if hour == 0 else hour,
            minute=default.minute if minute == 0 else minute,
            second=default.second if second == 0 else second,
        )
    # If the input contains information about a time zone, we need to convert
    # it to a datetime.timezone object
    if tzinfos is not None:
        if isinstance(tzinfos, dict):
            # If tzinfos is a dictionary, we need to convert its keys to
            # python time zone objects
            tzinfos = {
                tz: pytz.timezone(tzname)
                for tzname, tz in tzinfos.items()
                if tzname in pytz.all_timezones
            }
        elif not isinstance(tzinfos, dict) and callable(tzinfos):
            # If tzinfos is a function, we need to call it with the tzname
            # and tzoffset as parameters
            tzinfos = lambda tzname, tzoffset: tzinfos(tzname, tzoffset)
            # If the result is a python time zone object, we can use it to
            # convert the datetime object
            if isinstance(tzinfos, pytz.timezone):
                datetime_obj = tzinfos.localize(datetime_obj)
        else:
            raise TypeError("Invalid input: tzinfos must be a dictionary or a callable")
    # If the input contains information about an offset, we need to convert
    # it to a datetime.timedelta object
    if ignoretz:
        # If ignoretz is True, we need to return a naive datetime object
        return datetime_obj
    # Otherwise, we can return a datetime object with timezone information
    return datetime_obj

def fromutc(self, dt):
    """
    Given a timezone-aware datetime in a given timezone, calculates a
    timezone-aware datetime in a new timezone.

    Since this is the one time that we *know* we have an unambiguous
    datetime object, we take this opportunity to determine whether the
    datetime is ambiguous and in a "fold" state (e.g. if it's the first
    occurrence, chronologically, of the ambiguous datetime).

    :param dt:
        A timezone-aware :class:`datetime.datetime` object.
    """
    if dt.tzinfo is None:
        raise ValueError("dt parameter must be a timezone-aware datetime object")
    if not dt.tzinfo.utcoffset(dt):
        raise ValueError("dt parameter must have a non-zero utcoffset")
    new_tz = dt.tzinfo.fromutc(dt)
    if new_tz.tzname() == "Etc/UTC":
        return dt.astimezone(pytz.utc)
    else:
        return dt.astimezone(new_tz)

