def find_tags(text: str, replacer: callable = None) -> Tuple[Set[str], str]:
    tags = set()
    block = False
    output = text
    for word in text.split():
        if word == "`:":
            block = True
            continue
        if word == ":]":
            block = False
            continue
        if block or word[0] != "#":
            continue
        tags.add(word[1:])
        if replacer is not None:
            output = output.replace(word, replacer(word))
    return tags, output

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    no_tags_text = text
    code_block = False

    # Find all tags in the text
    for word in text.split():
        # Ignore tags inside code blocks
        if code_block and word.startswith("</code>"):
            code_block = False
        elif code_block:
            continue
        # Ignore tags starting with <
        elif word.startswith("<"):
            continue
        # Add the tag to the set
        else:
            tags.add(word)

    # Optionally replace tags
    if replacer:
        for tag in tags:
            no_tags_text = no_tags_text.replace(tag, replacer(tag))

    return tags, no_tags_text

def find_tags(text: str, replacer=None) -> Tuple[Set, str]:
    tags = set()
    regex = re.compile(r'<\/?\w+>')
    matches = regex.finditer(text)
    for match in matches:
        tag = match.group(0)
        if tag[1] == '/':
            continue
        tags.add(tag)
        if replacer:
            text = text.replace(tag, replacer(tag))
    return tags, text

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    clean_text = text

    # Find all tags in the text, ignoring those inside code blocks
    for tag in re.findall(r'<[^>]+>', text):
        if '{' not in tag and '}' not in tag:
            tags.add(tag)
            if replacer:
                clean_text = clean_text.replace(tag, replacer(tag))

    return tags, clean_text

def find_tags(text, replacer=None):
    tags = set()
    code_block = False
    current_word = ''

    for char in text:
        if char == '`':  # start of code block
            code_block = not code_block
        elif char == '`':  # end of code block
            code_block = False
        elif char == ' ' and not code_block:
            if current_word:
                tags.add(current_word)
                current_word = ''
        elif not code_block:
            current_word += char

    if replacer:
        for tag in tags:
            tag = replacer(tag)

    return tags, text

def process_text_links(text):
    links = []
    for match in re.finditer(r"(((http|https)://|www\.)([a-z0-9]*\-?[a-z0-9]+\.)*[a-z0-9][a-z0-9].*", text, flags=re.IGNORECASE):
        link = match.group()
        if "://" not in link:
            link = "http://" + link
        links.append(link)

    for link in links:
        linkified = "<a href='" + link + "'>" + link + "</a>"
        text = text.replace(link, linkified)

    return text

