def test_tag(tag):
    """Test a word whether it could be accepted as a tag."""
    # Check if the input is a non-empty string
    if not isinstance(tag, str) or not tag.strip():
        raise ValueError("Invalid input: tag must be a non-empty string")

    # Check if the tag is already a valid tag
    if tag in ["rock", "roll", "blues"]:
        return True

    # Check if the tag contains any invalid characters
    if re.search(r"\W", tag):
        return False

    # Check if the tag is longer than 20 characters
    if len(tag) > 20:
        return False

    # Check if the tag contains any duplicates
    if re.search(r"\b(\w)\1\b", tag):
        return False

    # Otherwise, the tag is considered acceptable
    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversion - child nodes are not recursively processed.
    """
    if not isinstance(node, xml.etree.ElementTree.Element):
        raise ValueError("Invalid input: node is not an xml.etree.ElementTree.Element")

    result = {}
    for child in node:
        tag = child.tag
        if tag not in result:
            result[tag] = []
        result[tag].append(child)

    return result

def xml_children_as_dict(node):
    if not isinstance(node, etree._Element):
        raise TypeError("node must be an ElementTree Element")
    children = node.getchildren()
    result = {}
    for child in children:
        if child.tag not in result:
            result[child.tag] = [child]
        else:
            result[child.tag].append(child)
    return result

def xml_children_as_dict(node):
    if not isinstance(node, etree.Element):
        raise ValueError("Expected etree.Element, got {} instead.".format(type(node).__name__))

    if not node.tag == "xml":
        raise ValueError("Expected <xml> element, got {} instead.".format(node.tag))

    children = {}
    for child in node:
        if child.tag not in children:
            children[child.tag] = []
        children[child.tag].append(child)

    return children

def xml_children_as_dict(node):
    if not isinstance(node, ElementTree.Element):
        raise ValueError("'node' must be an ElementTree.Element")
    return {child.tag: child for child in node}

