def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        result = json.loads(document)
    except JSONDecodeError:
        result = {}

    if "subject" in result and "aliases" in result and "links" in result:
        return result
    else:
        # Old format or invalid format
        try:
            xrd = XRD.parse(document)
        except XRDParseError:
            return {}

        subject = xrd["Subject"]["value"]
        aliases = [alias["value"] for alias in xrd["Aliases"]]
        links = [link["href"] for link in xrd["Links"]]
        return {"subject": subject, "aliases": aliases, "links": links}

