def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    for key, value in parser_dict.items():
        if isinstance(value, dict):
            if "include" in value:
                included_group = _get_group(value["include"])
                if included_group is None:
                    raise InvalidDictError(f"Group {included_group} is not found")
                value = {**value, **included_group}
            parser_dict[key] = _include_groups(value)
    return parser_dict

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """

    # Throw an error if `parser_dict` is not `dict`
    if not isinstance(parser_dict, dict):
        raise TypeError("'parser_dict' must be a dictionary")

    # Resolve the include dict directive by combining the included groups in `parser_dict`
    for group_name, group in parser_dict.items():
        if "include" in group:
            include_groups = group["include"]
            if not isinstance(include_groups, list):
                raise TypeError("'include' must be a list of group names")
            for include_group_name in include_groups:
                include_group_path = self._find_group_path(include_group_name)
                included_group = self._load_group(include_group_path)
                group[include_group_name] = included_group
            del group["include"]

    return parser_dict

def get_spec_defaults(self):
