    resolved_defaults = {}
    for arg, val in spec.defaults.items():
        if callable(val):
            resolved_defaults[arg] = val()
        else:
            resolved_defaults[arg] = val

    for arg, val in resolved_defaults.items():
        if isinstance(val, numbers.Integral):
            resolved_defaults[arg] = int(val)
        elif isinstance(val, numbers.Real):
            resolved_defaults[arg] = float(val)
        elif isinstance(val, bool):
