    for arg in spec.args:
        # 2.1 If the argument has a default value, resolve it using the spec's resolve_default method.
        if arg.default:
            resolved_defaults[arg] = spec.resolve_default(arg, values)
        # 2.2 If the argument has a default callable, resolve it.
        elif arg.default_factory:
            resolved_defaults[arg] = spec.resolve_callable(arg.default_factory)
