    spec = self.spec
    args = self.args
    if spec is None:
        raise Exception("Spec is not defined.")
    if args is None:
        raise Exception("Args is not defined.")
    # Iterate over spec and resolve default values
    default_values = {}
    for param_name, param in spec.items():
        if param["required"] and param["default"] is not None:
            default_values[param_name] = param["default"]
        elif "default" in param and param["default"] is not None:
            default_values[param_name] = param["default"]
        elif "env" in param and param["env"]:
            env_key = param["env"]
            if env_key in os.environ:
                default_values[param_name] = os.environ[env_key]
