    if not isinstance(spec_option, dict):
        raise TypeError("spec_option must be a dict")

    # Build the complex type instance
    complex_type = type(type_name, (argparse.ArgumentDefaultsHelpFormatter,), {
        "add_argument": lambda self, *arg, **kwargs: self.add_argument(subcommand,
                                                                       *arg, **kwargs),
        "arguments": argparse.Namespace()
