    if ansible_args and not isinstance(ansible_args, dict):
        raise ValueError("ansible_args must be a dict")

    args = ["ir-workspace", ir_workspace.name, "--plugin", ir_plugin.name, "--playbook", playbook_path]
    if verbose:
        args.extend(["-v", str(verbose)])
    if extra_vars:
        args.extend(["--extra-vars", json.dumps(extra_vars)])
    if ansible_args:
        args.extend(["--ansible-args", ",".join(ansible_args)])

    subprocess.run(["ansible-playbook"] + args)

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None, extra_vars=None, ansible_args=None):
    try:
        ansible_playbook_cli_command = f"ansible-playbook {playbook_path}"
        if verbose is not None:
            ansible_playbook_cli_command += f" -v {verbose}"
        if extra_vars is not None:
          for key, value in extra_vars.items():
              ansible_playbook_cli_command += f" -e \"{key}={value}\""
        if ansible_args is not None:
            ansible_playbook_cli_command += f" {' '.join(ansible_args)}"
        process = subprocess.run(ansible_playbook_cli_command, shell=True,
                                capture_output=True, text=True)
        if process.returncode != 0:
            raise Exception(process.stderr)
        elif process.stdout != "":
            return process.stdout
        else:
            return None
    except:
        raise Exception("Exception encountered while executing the Ansible playbook")

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    from infrared import AnsibleCLIRunner
    runner = AnsibleCLIRunner(cli_args, vars_dict)
    return runner.run()

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    ansible_vars = _format_vars(vars_dict)
    extra_vars = ansible_vars.replace("{}", "").strip()
    ansible_args = _format_ansible_args(cli_args, extra_vars)
    ansible_cmd = list(_ANSIBLE_BASE_CMD)
    ansible_cmd.extend(ansible_args)
    try:
        return _run_ansible_cmd(ansible_cmd, ir_workspace, ir_plugin)
    except Exception as e:
        raise AnsibleException(str(e))

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    try:
        playbook_args = [
            cli_args, 
            "-e", 
            json.dumps(vars_dict), 
            "-i", 
            ir_workspace.get_ansible_inventory(), 
            "-vvvv"
        ]
        p = subprocess.run(
            [ir_plugin.ansible_path, "-m", "command", " ".join(playbook_args)],
            stdout=subprocess.PIPE, 
            stderr=subprocess.PIPE,
        )
        if p.returncode != 0:
            raise CalledProcessError(
                'failed to run playbook "{}"'.format(cli_args), p
            )
        return json.loads(p.stdout)
    except CalledProcessError as e:
        # display error and terminate the process
        print("Encountered error during playbook execution: {}".format(e))
        sys.exit(1)

def __make_ansible_cli_command(cli_args, vars=None, config=None):
    args = ['ansible-playbook']
    if vars:
        args += ['--extra-vars', json.dumps(vars)]
    if config:
        for k, v in config.items():
            args += [f'--{k}', v]
    args += cli_args
    return ansible.run_command(args)

def __format_ansible_results(results, ir_workspace):
    if 'facts' in results:
        facts = ansible.sanitize_facts(results['facts'], ir_workspace.network_configuration)
        return json.dumps(facts)
    elif 'changed' in results:
        return f"{results['changed']} tasks were changed"
    return f"{results['results']}"

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    ansible_opts = []
    ansible_opts.append("--extra-vars")
    ansible_opts.extend(["=", json.dumps(vars_dict)])
    ansible_opts.extend(cli_args)
    try:
        return ansible_runner.run(ansible_opts, wd=ir_workspace.abs_path)
    except ansible_errors.AnsibleConfigError as e:
        raise InfraredCliException(e) from e
    except ansible_errors.AnsibleRunnerException as e:
        raise InfraredCliException(e) from e

