def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Dictionary of command arguments and their respective types
    arg_types = self.get_arg_types(parser_name)

    try:
        # Loop through the arguments in values_dict
        for arg_name, arg_value in values_dict.items():
            # Check if arg_name is in arg_types
            if arg_name in arg_types:
                # Get the arg_type and convert arg_value accordingly
                arg_type = arg_types[arg_name]
                if arg_type == int:
                    values_dict[arg_name] = int(arg_value)
                elif arg_type == float:
                    values_dict[arg_name] = float(arg_value)
                elif arg_type == bool:
                    values_dict[arg_name] = bool(arg_value)
                else:
                    # Do not convert to anything for other types
                    pass
            else:
                # Raise an exception if arg_name is not in arg_types
                raise ValueError(f"Unknown argument {arg_name} for parser {parser_name}")
    except ValueError:
        # Raise an exception if there is an error converting values_dict
        raise

def _convert_non_cli_args(self, parser_name, values_dict):
