def _convert_non_cli_args(self, parser_name, values_dict):
    cmd_info = self.get_command_info(parser_name)
    arg_types = cmd_info.get("arg_types", {})
    for arg_name, value in values_dict.items():
        if arg_name in arg_types:
            arg_type = arg_types[arg_name]
            if arg_type == "bool":
                values_dict[arg_name] = parse_bool_arg(value)
            elif arg_type == "int":
                values_dict[arg_name] = parse_int_arg(value)
            elif arg_type == "float":
                values_dict[arg_name] = parse_float_arg(value)
            elif arg_type == "str":
