def _convert_non_cli_args(parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param."""
    if parser_name == "main":
        for arg in values_dict.keys():
            if arg in ["debug", "verbose", "quiet"]:
                values_dict[arg] = bool(values_dict[arg])
            if arg in ["host", "user", "password"]:
                values_dict[arg] = str(values_dict[arg])
            if arg in ["port"]:
                values_dict[arg] = int(values_dict[arg])
    elif parser_name == "virsh":
        for arg in values_dict.keys():
            if arg in ["max-requests"]:
                values_dict[arg] = int(values_dict[arg])
    elif parser_name == "ospd":
        for arg in values_dict.keys():
            if arg in ["dry-run"]:
                values_dict[arg] = bool(values_dict[arg])
            if arg in ["threshold"]:
                values_dict[arg] = float(values_dict[arg])
    elif parser_name == "osps":
        for arg in values_dict.keys():
            if arg in ["limit"]:
                values_dict[arg] = int(values_dict[arg])
    else:
        raise ValueError("Invalid parser name")
    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    if not plugin_dir:
        raise ValueError("Missing argument: plugin_dir")

    with open(os.path.join(plugin_dir, "spec.json")) as f:
        spec = json.load(f)

    flat_dict = {}

    for key, value in spec.items():
        if isinstance(value, dict):
            flat_dict.update({f"{key}.{k}": v for k, v in value.items()})
        else:
            flat_dict[key] = value

    return flat_dict

def get_plugin_spec_flatten_dict(plugin_dir):
