def get_plugin_spec_flatten_dict(plugin_dir):
    plugin_spec = load_plugin_spec(plugin_dir)
    flatten_dict = defaultdict(dict)
    for key, value in plugin_spec.items():
        if isinstance(value, dict):
            for sub_key, sub_value in value.items():
                flatten_dict[f"{key}.{sub_key}"] = sub_value
        else:
            flatten_dict[key] = value
    return flatten_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    plugin_spec_dict = {}
    for filepath in glob.glob(f"{plugin_dir}/*.json"):
        with open(filepath) as f:
            plugin_spec = json.load(f)
            plugin_spec_dict.update(plugin_spec)
    return plugin_spec_dict

